/* Moderator console (W6, W7, W11, W19, W20, I3, I5, C2) and admin (J1, W21, I1, I2, H5, F4, F5, scheduler),
   aligned to the iteration 2 API:
   GET /moderation/cases (CaseQueueOut: no names), GET /moderation/cases/{id} (ModeratorCaseOut: names),
   POST .../decision (DecisionIn), POST .../information-requests, POST .../appeal-decision,
   POST /moderation/decisions/{id}/reversal, GET /moderation/memberships, POST .../memberships/{id}/decision,
   GET /admin/audit, POST /admin/audit/{source}/{id}/unmask, POST /internal/jobs/run */

const PRIO = { 1: ["high", "Priority 1", "flame"], 2: ["med", "Priority 2", "equal"], 3: ["low", "Priority 3", "chevron-down"] };
const PRI = { high: ["High", "flame"], med: ["Medium", "equal"], low: ["Low", "chevron-down"] };
const POSS = { NOT_HANDED_OVER: ["Never handed over", "Ends as a no-show, dates released"], WITH_BORROWER: ["Still with the borrower", "Back to ACTIVE, dates stay held"], RETURNED: ["Back with the lender", "Ends as COMPLETED"], LOST: ["Lost", "Ends as COMPLETED"] };
const POSS_BY_STAGE = { ACCEPTED: ["NOT_HANDED_OVER"], ACTIVE: ["WITH_BORROWER", "RETURNED", "LOST"], RETURN_INITIATED: ["WITH_BORROWER", "RETURNED", "LOST"] };
const REASSESS = ["locality_inconclusive", "locality_conflict", "engine_failure"];
const kindOf = c => c.status === "APPEALED" ? "appeal" : c.trigger_type === "DISPUTE" ? "dispute" : "hold";
const trail = rows => `<ul class="events-tr mt-4">${rows.map(([t, k, x]) => `<li><span class="tm">${t}</span><span class="pp ${k}"></span><span class="mono xs">${x}</span></li>`).join("")}</ul>`;

const consoleHead = (t, s, a = "") => `<header class="ph" style="padding-top:24px"><div class="between" style="align-items:flex-end;flex-wrap:wrap"><div><h1 style="font-size:clamp(1.5rem,2.6vw,2rem)">${t}</h1>${s ? `<p>${s}</p>` : ""}</div>${a ? `<div class="btns">${a}</div>` : ""}</div></header>`;
/* CaseQueueOut: trigger, reason, status, priority, item. Never the people involved. */
function caseList(sel, base) {
  return `<div class="list">${DB.cases.map(c => { const [ic, tn, lab] = TRIGGER[c.trigger_type], [pk, pl, pi] = PRIO[c.priority], [sl, st] = CASE_ST[c.status];
    return `<a class="case" href="#${base}/case/${c.id}" data-k="${kindOf(c)}" ${c.id === sel ? 'aria-current="true"' : ""}>
    <div class="between"><span class="prio ${pk}">${icon(pi)}${pl}</span><span class="xs faint">${c.opened} ago</span></div>
    <div class="row mt-2" style="align-items:flex-start">${photo(I(c.item).photo, { w: 120, ratio: "1", alt: "" }).replace('class="ph-img ', 'style="width:44px;border-radius:10px" class="ph-img ')}<div class="grow"><b class="small" style="display:block;line-height:1.35">${c.reason}</b><span class="xs muted">${I(c.item).title}</span></div></div>
    <div class="row-wrap mt-2"><span class="badge ${tn}">${icon(ic)}${c.dispute_reason ? DISPUTE_R[c.dispute_reason][1] : lab}</span><span class="status ${st}">${sl}</span><span class="mono xs faint">${c.id}</span></div></a>`; }).join("")}</div>`;
}
const caseTop = (c, note) => { const [sl, st] = CASE_ST[c.status];
  return `<div class="card card-pad-lg"><div class="between" style="align-items:flex-start;flex-wrap:wrap;gap:10px"><div><div class="xs faint mono">${c.id} · ${c.trigger_type}${c.hold_reason ? " · " + c.hold_reason : ""}</div><h2 class="mt-1" style="font-size:1.35rem">${c.reason}</h2></div><span class="status ${st}">${sl}</span></div>
    <div class="grid-2 mt-4" style="gap:10px"><div class="row small">${av(c.borrower, "xs")}<span><b>${U(c.borrower).name}</b> <span class="faint">· borrower</span></span></div><div class="row small">${av(c.lender, "xs")}<span><b>${U(c.lender).name}</b> <span class="faint">· lender</span></span></div></div>
    <p class="small muted mt-3">${icon("package", "i-sm")} ${I(c.item).title} · ${c.period} · loan state <span class="mono">${c.state}</span></p><p class="small muted mt-1">${icon("timer", "i-sm")} ${note}</p></div>`; };

/* DecisionIn: kind, reason (required, <= 1000), safeguards (SAFEGUARDS_IMPOSED only), at_fault + possession (disputes) */
function decisionForm(c) {
  const k = kindOf(c), eng = c.hold_reason === "engine_failure";
  const kinds = k === "dispute" ? [] : [["CLEARED", "Clear", REASSESS.includes(c.hold_reason) ? "Back to LOCALITY_CHECKED, and the assessment runs again." : "The existing evidence report goes to the lender (ASSESSED).", "check"], ...(eng ? [] : [["SAFEGUARDS_IMPOSED", "Clear with safeguards", "Choose at least one safeguard. The lender sees it marked “set by a moderator”.", "shield-check"]]), ["RESTRICTED", "Restrict", "The request is declined. Only a person can do this, and the borrower can appeal.", "ban"]];
  const poss = POSS_BY_STAGE[c.dispute_stage] || POSS_BY_STAGE.ACTIVE;
  return `<form class="card card-pad-lg" id="dec" style="border:1.5px solid var(--primary)" novalidate><h3>Your decision</h3>
    ${k === "dispute" ? `<p class="small muted mt-1">Resolves the dispute (<span class="mono">DISPUTE_RESOLVED</span>). The finding becomes evidence for both people.</p>
      <div class="field mt-4"><div class="label">Who was responsible?</div><div class="opts cols-2">${[["borrower", "The borrower", "user"], ["lender", "The lender", "user-round"], ["none", "Nobody", "scale"]].map(([v, t, ic], i) => `<label class="opt" style="padding:11px"><input type="radio" name="f" value="${v}" ${i === 0 ? "checked" : ""}>${tone(ic, "neutral", 30)}<span><strong class="small">${t}</strong></span></label>`).join("")}</div></div>
      <div class="field"><div class="label">Where is the item now?</div><div class="opts cols-2">${poss.map((p, i) => `<label class="opt" style="padding:11px"><input type="radio" name="p" value="${p}" ${i === (poss.length > 1 ? 1 : 0) ? "checked" : ""}>${tone(p === "LOST" ? "package-x" : p === "WITH_BORROWER" ? "hand" : "package-check", "neutral", 30)}<span><strong class="small">${POSS[p][0]}</strong><p class="xs">${POSS[p][1]}</p></span></label>`).join("")}</div><span class="help">Only the options that fit where the dispute was raised from (${c.dispute_stage}) are offered.</span></div>`
      : `<div class="opts mt-4">${kinds.map(([v, t, d, ic], i) => `<label class="opt"><input type="radio" name="d" value="${v}" ${i === 0 ? "checked" : ""}>${tone(ic, "neutral", 34)}<span><strong>${t}</strong><p>${d}</p></span><span class="tick">${icon("check")}</span></label>`).join("")}</div>
      ${eng ? `<p class="xs faint mt-2">${icon("info", "i-sm")} No assessment exists after an engine failure, so safeguards can't be imposed (UC-I4 3c).</p>` : `<div class="field mt-4" id="sgf" hidden><div class="label">Safeguards</div><div class="stack" style="gap:2px">${Object.entries(DB.safeguards).map(([code, l]) => `<label class="check" style="padding:7px 0;border:0"><input type="checkbox" value="${code}"><span><span style="color:var(--text)">${l}</span> <span class="mono xs faint">${code}</span></span></label>`).join("")}</div></div>`}`}
    <div class="field"><label class="label" for="why">Reason <span class="req">· both parties see this</span></label><textarea class="textarea" id="why" maxlength="1000" placeholder="What evidence led to this decision?"></textarea><div class="between xs faint mt-1"><span>Required</span><span><span id="wc">0</span>/1000</span></div><div id="we"></div></div>
    <p class="xs faint mt-2">${icon("scroll-text", "i-sm")} Recorded first, then applied as one lifecycle event that points to it: ${k === "dispute" ? "<code class='mono'>dispute_resolved</code>" : "<code class='mono'>hold_cleared</code> or <code class='mono'>request_declined</code>"}.</p>
    <div class="btns mt-4"><button class="btn btn-primary" type="submit">Record decision</button>${k === "dispute" ? `<button class="btn btn-outline" type="button" id="ai">${icon("message-square-text")}Ask for information</button>` : ""}</div></form>`;
}
function bindDecision(base, c) {
  const f = $("#dec"); if (!f) return; const w = $("#why");
  w.oninput = () => { $("#wc").textContent = w.value.length; w.removeAttribute("aria-invalid"); $("#we").innerHTML = ""; };
  $$("input[name=d]").forEach(r => r.onchange = () => { if ($("#sgf")) $("#sgf").hidden = $("input[name=d]:checked").value !== "SAFEGUARDS_IMPOSED"; });
  f.onsubmit = e => { e.preventDefault();
    const err = m => { $("#we").innerHTML = `<p class="err">${icon("circle-alert")}${m}</p>`; refreshIcons(); };
    if (!w.value.trim()) { w.setAttribute("aria-invalid", "true"); w.focus(); return err("Write the reason before recording the decision."); }
    const kind = $("input[name=d]:checked")?.value || "DISPUTE_RESOLVED", sgs = $$("#sgf input:checked").map(x => x.value);
    if (kind === "SAFEGUARDS_IMPOSED" && !sgs.length) return err("Name at least one safeguard.");
    const summary = kind === "DISPUTE_RESOLVED" ? `DISPUTE_RESOLVED · at fault: ${$("input[name=f]:checked").value} · possession: ${$("input[name=p]:checked").value}` : kind + (sgs.length ? " · " + sgs.join(", ") : "");
    dialog(`<h2>Record this decision?</h2><p class="muted mt-2">It's recorded with your name and can't be edited. Either party can appeal once within ${DB.timers.appealWindowD} days, and a reversal keeps both decisions in the log.</p><div class="card card-2 mt-4 small"><b class="mono xs">${summary}</b><p class="mt-1">${esc(w.value)}</p></div><div class="btns mt-6"><button class="btn btn-primary" id="cm" type="button">Record decision</button><button class="btn btn-ghost" data-close type="button">Go back</button></div>`, "Confirm");
    $("#cm").onclick = () => { closeDialog(); $(".detail").innerHTML = `<div class="card card-pad-lg">${done("Decision recorded", "Both parties are notified with your reason. The audit log has the entry.")}<div class="btns" style="justify-content:center"><a class="btn btn-primary" href="#${base}">Next case</a></div></div>`; refreshIcons(); }; };
  $("#ai")?.addEventListener("click", () => dialog(`<h2>Ask for information</h2><p class="small muted mt-1">The case moves to “waiting for a reply”. They have ${DB.timers.partyResponseH} hours; after that the case comes back to you to decide with what's there.</p><div class="field mt-6"><div class="label">Ask</div>${seg([["BORROWER", "Borrower"], ["LENDER", "Lender"], ["BOTH", "Both"]])}</div><div class="field"><label class="label" for="iq">Question</label><textarea class="textarea" id="iq" maxlength="1000" style="min-height:80px">Do you have photos from when you collected the chairs?</textarea></div><button class="btn btn-primary btn-block mt-6" data-close type="button" onclick="toast('Question sent · ${DB.timers.partyResponseH} h deadline')">Send question</button>`, "Ask"));
}
const statements = c => (c.statements || []).length ? `<div class="card"><h3>Statements</h3>${c.statements.map(s => `<div style="padding:12px 0;border-top:1px solid var(--border);margin-top:10px"><div class="between"><b class="small">${s.author_name} <span class="faint" style="font-weight:400">· ${s.author_role.toLowerCase()}</span></b><span class="xs faint">${s.at}</span></div><p class="small mt-2">“${s.statement}”</p></div>`).join("")}</div>` : "";
function disputeD(c) {
  const it = I(c.item), auto = !c.raised_by_role, q = c.information_request;
  const bEv = DB.myEvidence.roles[0].factors[0], lEv = (DB.lenderEv[c.lender] || DB.lenderEv.u4)?.factors?.[0];
  return `<div class="stack-lg">${caseTop(c, auto ? `Opened by the scheduler ${c.opened} ago: ${DB.timers.overdueLimitH} h after the due date, after ${DB.timers.minReminders} reminders.` : `Raised by the ${c.raised_by_role.toLowerCase()} ${c.opened} ago (${DISPUTE_R[c.dispute_reason][1].toLowerCase()}). With no moderator in the community, it would go to an admin.`)}
    ${q ? `<div class="card card-2 row" style="align-items:flex-start">${tone("message-square-text", "sky", 36)}<div class="grow"><div class="between"><b class="small">You asked the ${q.to.toLowerCase()}</b>${cd(q.mins)}</div><p class="small mt-1">“${q.question}”</p><p class="xs faint mt-1">Deadline ${q.deadline}</p></div></div>` : ""}
    ${statements(c)}
    ${auto ? `<div class="card"><h3>What happened</h3>${trail([["1 Oct", "", "handover_confirmed · ACCEPTED → ACTIVE"], ["11 Oct 20:00", "h", "Due date passed"], ["11 Oct 20:05", "f", "reminder_sent · job return_reminder"], ["12 Oct 08:00", "f", "reminder_sent · second"], ["14 Oct 20:00", "a", "dispute_opened · overdue_escalation · ACTIVE → DISPUTED"]])}<p class="xs faint mt-3">Each job is idempotent: a rerun wouldn't send duplicate notices or open a second dispute.</p></div>`
    : `<div class="card"><h3>Photos</h3><div class="cmp mt-4"><div><div class="lab">${icon("package-check")}Handover</div>${photo(it.photo, { w: 500, ratio: "1", alt: "Handover" })}</div><div><div class="lab">${icon("undo-2")}Return</div>${photo(it.photo, { w: 500, ratio: "1", alt: "Return", cls: "flag", inner: '<span class="pin" style="left:28%;top:56%">1</span><span class="pin" style="left:64%;top:62%">2</span>' })}</div></div>
        <div class="check-row mt-2"><div><b class="small">“All 20 chairs, legs firm”</b><div class="xs" style="color:var(--primary-ink)">Handover checklist, confirmed by the borrower</div></div><span class="badge coral">${icon("x")}2 cracked at return</span></div></div>
      <div class="card"><h3>Event trail</h3>${trail([["1 Oct 17:02", "", "request_accepted · ASSESSED → ACCEPTED"], ["1 Oct 18:04", "", "condition report HANDOVER · deposit_received"], ["1 Oct 18:10", "", "handover_confirmed · ACCEPTED → ACTIVE"], ["3 Oct 20:15", "", "return_initiated · ACTIVE → RETURN_INITIATED"], ["15 Oct 18:27", "a", "dispute_opened · DAMAGE · RETURN_INITIATED → DISPUTED"], ["16 Oct 10:42", "h", "case: information requested · BORROWER · 72 h"]])}<p class="xs faint mt-3">From the append-only event store.</p></div>`}
    <div class="card"><h3>Evidence about both</h3><p class="small muted mt-1">An open dispute isn't counted for either person until you decide.</p><div class="grid-2 mt-4"><div class="card card-2"><div class="row small">${av(c.lender, "xs")}<b>${U(c.lender).short} as a lender</b></div>${lEv ? factorList([lEv]) : ""}</div><div class="card card-2"><div class="row small">${av(c.borrower, "xs")}<b>${U(c.borrower).short} as a borrower</b></div>${factorList([bEv])}</div></div></div>
    ${decisionForm(c)}</div>`;
}
function appealD(c) {
  const it = I(c.item), d = c.decisions[0];
  return `<div class="stack-lg">${caseTop(c, `Appealed ${c.appeal.filed} by the ${c.appeal.by_role.toLowerCase()}. You're the second moderator: the first decider can't decide an appeal.`)}
    <div class="card"><h3>Original decision</h3><div class="row mt-3">${av("mod2", "sm")}<div><b class="small">${d.decider}</b><div class="xs faint">${d.decided} · <span class="mono">${d.kind}</span> · at fault: ${d.at_fault} · ${d.possession}</div></div></div><p class="mt-3">“${d.reason}”</p></div>
    <div class="card"><h3>The appeal</h3><p class="mt-3" style="font-size:16.5px">“${c.appeal.reason}”</p>
      <div class="cmp mt-4"><div><div class="lab">${icon("package-check")}Handover photo on file</div>${photo(it.photo, { w: 500, ratio: "1", alt: "" })}</div><div><div class="lab">${icon("undo-2")}Return photo on file</div>${photo(it.photo, { w: 500, ratio: "1", alt: "", cls: "flag", inner: '<span class="pin" style="left:60%;top:58%">!</span>' })}</div></div></div>
    <div class="card"><h3>If you overturn it</h3><div class="stack mt-4">${[["history", "sky", "Both decisions stay in the log", "The first is marked reversed, never deleted"], ["flag", "saffron", "The loan's outcomes are flagged", "FLAGGED_FOR_REEVALUATION, so the evidence is recalculated for both people"]].map(([ic, t, h, x]) => `<div class="row" style="align-items:flex-start">${tone(ic, t, 34)}<div><b class="small">${h}</b><p class="xs muted">${x}</p></div></div>`).join("")}</div></div>
    <form class="card card-pad-lg" id="apd" style="border:1.5px solid var(--primary)"><h3>Appeal decision</h3><div class="opts mt-4">${[["UPHELD", "Uphold", "The first decision stands and the appeal closes.", "check-check"], ["OVERTURNED", "Overturn", "The first decision is reversed. Its outcomes are re-evaluated.", "rotate-ccw"]].map(([v, t, x, ic], i) => `<label class="opt"><input type="radio" name="ar" value="${v}" ${i === 0 ? "checked" : ""}>${tone(ic, "neutral", 34)}<span><strong>${t}</strong><p>${x}</p></span><span class="tick">${icon("check")}</span></label>`).join("")}</div>
      <div class="field"><label class="label" for="arw">Reason <span class="req">· both parties see this</span></label><textarea class="textarea" id="arw" maxlength="1000"></textarea></div><button class="btn btn-primary mt-4" type="submit">Record appeal decision</button></form></div>`;
}
function holdD(c) {
  const it = I(c.item), hr = c.hold_reason;
  const FAISAL = { borrower: c.borrower, lede: "Faisal has 1 verified loan, a book. This projector is a high-value item, so that history is thin and not similar.", moderator_safeguards: [],
    assessment: { assurance_state: "REVIEW_RECOMMENDED", policy_decision: "RESTRICT_HIGH_VALUE", rule_fired: "R4", config_version: DB.configVersion, posterior_mean: 0.67, ci90_low: 0.22, ci90_high: 0.97, effective_evidence: 0.6, verified_loans: 1, community: { reliability: 0, paths: [] }, manipulation_risk: 6, manipulation_level: 1, safeguards: sg("HIGH_VALUE_DEPOSIT_RECORD", "HANDOVER_PHOTOS"), explanation: "High-value item on weak or dissimilar evidence; a moderator reviews it first. Direct evidence: 1 verified loan(s), weighted for recency and similarity to 0.6 effective outcomes. Community paths from the lender: none found. Manipulation checks: no notable signals (level 1 of 4). Decision support, not a guarantee." } };
  const body = hr === "manipulation_risk" ? `<div class="card"><h3>Evidence and unusual activity, side by side</h3><p class="small muted mt-1">Never averaged. A strong history doesn't cancel unusual activity, and the activity alone never restricts anyone.</p>
      <div class="grid-2 mt-4"><div class="card card-2">${stateChip("SUFFICIENT_EVIDENCE")}<p class="small mt-3">8 verified loans in 3 weeks.</p></div><div class="card card-2"><div class="between"><b class="small">Manipulation risk</b><span class="badge violet">Level ${c.risk.level} of 4</span></div><div class="meter mt-4"><i style="left:${c.risk.score}%"></i></div><div class="between xs faint mt-2"><span>0</span><span>Score ${c.risk.score}</span><span>100</span></div></div></div>
      <h4 class="mt-6 small">Signals found</h4>${[...c.risk.signals, ["Ratings arriving faster than usual (S2)", 0.3]].map(([l, v]) => `<div class="signal"><span class="small">${l}</span><span class="sb"><i class="${v < 0.5 ? "lo" : ""}" style="width:${v * 100}%"></i></span><b class="small mono">${v.toFixed(2)}</b></div>`).join("")}
      <p class="xs faint mt-3">Two signals at 0.5 or above corroborate each other, so it's level 4 and held (ADR-0007). Patterns to check, not proof.</p></div>`
    : hr === "engine_failure" ? `<div class="card">${empty("server-crash", "neutral", "No assessment exists", "The assessment timed out at 2,000 ms and the failure was logged. No state was assigned, and nothing was assumed. Clearing it runs the assessment again.")}</div>`
    : hr?.startsWith("locality") ? `<div class="card"><h3>Stored locality result</h3><p class="small muted mt-1">Only the coarse result is kept. No position, distance or address.</p><div class="list mt-4" style="border:0"><div class="li" style="padding:12px 0">${tone("map-pin-off", "coral", 38)}<span class="grow"><span class="d">Outcome</span><span class="t mono">CONFLICTING</span></span></div><div class="li" style="padding:12px 0">${tone("radar", "saffron", 38)}<span class="grow"><span class="d">Boundary signal</span><span class="t mono">OUTSIDE</span></span></div></div><p class="small mt-2">Clearing sends the request back to <span class="mono">LOCALITY_CHECKED</span>, so the evidence report is prepared again.</p></div>`
    : evidence(FAISAL, { name: "Faisal", moderator: true });
  return `<div class="stack-lg">${caseTop(c, `Held ${c.opened} ago · ${HOLD[hr]}. The lender hasn't seen this request yet.`)}${body}
    <div class="card"><h3>What each decision does</h3><p class="small muted mt-1">Exits from HELD_FOR_REVIEW (ADR-0003). This case's row is highlighted.</p><div style="overflow-x:auto"><table class="xt mt-3"><thead><tr><th>Hold reason</th><th>Clear</th><th>With safeguards</th><th>Restrict</th></tr></thead><tbody>${[["locality_inconclusive / locality_conflict", "→ LOCALITY_CHECKED, assess again", "→ LOCALITY_CHECKED, with safeguards", "→ DECLINED"], ["manipulation_risk / high_value_low_confidence", "→ ASSESSED", "→ ASSESSED, with safeguards", "→ DECLINED"], ["engine_failure", "→ LOCALITY_CHECKED, assess again", "Not allowed", "→ DECLINED"]].map((r, i) => `<tr class="${(i === 0 && hr?.startsWith("locality")) || (i === 1 && ["manipulation_risk", "high_value_low_confidence"].includes(hr)) || (i === 2 && hr === "engine_failure") ? "cur" : ""}">${r.map(x => `<td>${x}</td>`).join("")}</tr>`).join("")}</tbody></table></div></div>
    ${decisionForm(c)}</div>`;
}
function queue(sel, base, admin) {
  const c = DB.cases.find(x => x.id === sel), n = k => DB.cases.filter(x => kindOf(x) === k).length, hi = DB.cases.filter(x => x.priority === 1).length;
  return { title: c ? "Case " + c.id : "Case queue", nav: "queue",
    html: `${consoleHead(admin ? "Escalations" : "Good morning, Imran", admin ? "Cases in communities with no moderator, or where a moderator is a party." : `${DB.cases.length} cases in Block C. ${hi} are priority 1.`)}
      ${c ? "" : `<div class="grid-4" data-stagger><div class="card" style="background:var(--text);color:var(--bg);border:0"><div class="xs" style="opacity:.7">Priority 1</div><div class="kpi mt-2" data-count="${hi}">0</div></div><div class="card"><div class="xs faint">Disputes</div><div class="kpi mt-2" data-count="${n("dispute")}">0</div></div><div class="card"><div class="xs faint">Holds</div><div class="kpi mt-2" data-count="${n("hold")}">0</div></div><div class="card"><div class="xs faint">Appeals</div><div class="kpi mt-2" data-count="${n("appeal")}">0</div></div></div>`}
      <div class="split-v mt-6 ${c ? "sel" : ""}"><div class="qlist"><div class="chips" data-chips id="qf" style="margin-bottom:12px">${[["all", "All", DB.cases.length], ["dispute", "Disputes", n("dispute")], ["hold", "Holds", n("hold")], ["appeal", "Appeals", n("appeal")]].map(([k, l, x], i) => `<button class="chip" type="button" data-f="${k}" aria-pressed="${i === 0}">${l}<span class="n">${x}</span></button>`).join("")}</div>${caseList(sel, base)}<p class="xs faint mt-3">${icon("eye-off", "i-sm")} The queue shows no names. Ordered by priority, then age; evidence estimates never order it.</p></div>
        <div class="detail">${c ? `<a class="back mob" href="#${base}">${icon("arrow-left")}All cases</a>` + ({ dispute: disputeD, appeal: appealD, hold: holdD }[kindOf(c)])(c) : `<div class="card">${empty("mouse-pointer-click", "neutral", "Pick a case", "Start with priority 1. A dispute pauses a loan until you decide.")}</div>`}</div></div>`,
    after() {
      if (c) bindDecision(base, c);
      $("#apd")?.addEventListener("submit", e => { e.preventDefault(); if (!$("#arw").value.trim()) { $("#arw").setAttribute("aria-invalid", "true"); return toast("Write the reason first.", { ic: "info" }); } const v = $("input[name=ar]:checked").value; $(".detail").innerHTML = `<div class="card card-pad-lg">${done(v === "UPHELD" ? "Decision upheld" : "Decision overturned", v === "UPHELD" ? "The appeal is closed and both parties are told." : "The first decision is marked reversed and 2 loan outcomes are flagged for re-evaluation.")}<div class="btns" style="justify-content:center"><a class="btn btn-primary" href="#${base}">Next case</a></div></div>`; refreshIcons(); });
      $("#qf").addEventListener("click", e => { const b = e.target.closest("[data-f]"); if (b) $$(".case").forEach(r => (r.hidden = !(b.dataset.f === "all" || r.dataset.k === b.dataset.f))); });
    } };
}
route("/mod", () => queue(null, "/mod"));
route("/mod/case/:id", ({ id }) => queue(id, "/mod"));
route("/admin/cases", () => queue(null, "/admin/cases", true));
route("/admin/cases/case/:id", ({ id }) => queue(id, "/admin/cases", true));

/* ---------------- W11: join requests (MembershipQueueOut: coarse results only) ---------------- */
const LOC = { VERIFIED: ["green", "Verified", "map-pin-check"], INCONCLUSIVE: ["saffron", "Inconclusive", "map-pin"], CONFLICTING: ["coral", "Conflicting", "map-pin-off"] };
const BOUND = { INSIDE: "Inside the boundary", NEAR_BOUNDARY: "Near the boundary", OUTSIDE: "Outside the boundary", UNAVAILABLE: "No location shared" };
const MST = { PENDING: ["saffron", "Pending"], AWAITING_INFORMATION: ["sky", "Waiting for a reply"], APPROVED: ["green", "Approved"], REJECTED: ["coral", "Rejected"] };
const flagsOf = r => [r.mock_provider_detected && "Mock location app detected", r.duplicate_suspected && "Possible duplicate account", r.permission_refused && "Location permission refused"].filter(Boolean);
function members(sel) {
  const m = DB.joinRequests.find(x => x.id === sel), open = DB.joinRequests.filter(r => ["PENDING", "AWAITING_INFORMATION"].includes(r.status)).length;
  const list = `<div class="list">${DB.joinRequests.map(r => `<a class="case" href="#/mod/members/${r.id}" ${r.id === sel ? 'aria-current="true"' : ""}><div class="row"><span class="avatar">${r.initials}</span><div class="grow"><b class="small">${r.applicant_name}</b><div class="xs muted">${r.invitation_used ? "With an invitation" : "No invitation"} · ${r.requested} ago</div></div><span class="status ${MST[r.status][0]}">${MST[r.status][1]}</span></div><div class="row-wrap mt-2"><span class="badge ${LOC[r.locality_outcome][0]}">${icon(LOC[r.locality_outcome][2])}${LOC[r.locality_outcome][1]}</span>${[r.mock_provider_detected && "Mock location", r.duplicate_suspected && "Duplicate?"].filter(Boolean).map(f => `<span class="badge coral">${icon("flag")}${f}</span>`).join("")}</div></a>`).join("")}</div>`;
  let d;
  if (!m) d = `<div class="card">${empty("user-check", "neutral", "Pick a request", "Inconclusive and conflicting results always come to a person. Nobody is rejected automatically.")}</div>`;
  else if (m.decided_by) d = `<div class="stack-lg"><div class="card card-pad-lg row"><span class="avatar xl">${m.initials}</span><div><h2>${m.applicant_name}</h2><p class="small muted">${LOC[m.locality_outcome][1]} · ${BOUND[m.boundary_signal]}</p></div></div><div class="card card-2 row" style="align-items:flex-start">${tone("users", "sky", 36)}<div><b>${m.decided_by} approved this</b><p class="small muted">A decision is applied once. If it was wrong, reverse it with a reason: both decisions stay in the log.</p></div></div><div class="card">${timeline([{ s: "done", t: "Request sent", d: "14 Oct" }, { s: "done", t: `APPROVED by ${m.decided_by}`, d: "15 Oct, 9:03 pm · “Inside the boundary and the invitation is valid”" }, { s: "todo", t: "REVERSED, only if needed" }])}</div><div class="btns"><a class="btn btn-outline" href="#/mod/members">Back to the queue</a><button class="btn btn-ghost" type="button" id="rv">${icon("rotate-ccw")}Reverse with a reason</button></div></div>`;
  else d = `<div class="stack-lg"><div class="card card-pad-lg"><div class="row" style="gap:18px"><span class="avatar xl">${m.initials}</span><div><h2 style="font-size:1.4rem">${m.applicant_name}</h2><p class="small muted">Asked to join Block C ${m.requested} ago</p></div></div></div>
    <div class="card"><h3>What the check stored</h3><p class="small muted mt-1">Only coarse results. Never a position, distance or address.</p>
      <div class="list mt-4" style="border:0">
        <div class="li" style="padding:12px 0">${tone(LOC[m.locality_outcome][2], LOC[m.locality_outcome][0], 38)}<span class="grow"><span class="d">Locality outcome</span><span class="t">${LOC[m.locality_outcome][1]} <span class="mono xs faint">${m.locality_outcome}</span></span></span></div>
        <div class="li" style="padding:12px 0">${tone("radar", "sky", 38)}<span class="grow"><span class="d">Boundary signal</span><span class="t">${BOUND[m.boundary_signal]} <span class="mono xs faint">${m.boundary_signal}</span></span></span></div>
        <div class="li" style="padding:12px 0">${tone("ticket", m.invitation_used ? "green" : "neutral", 38)}<span class="grow"><span class="d">Invitation</span><span class="t">${m.invitation_used ? "A valid code from a member was used" : "No invitation code"}</span></span></div></div>
      ${flagsOf(m).map(f => `<div class="card card-2 row mt-2" style="align-items:flex-start">${tone("flag", "coral", 34)}<div><b class="small">${f}</b><p class="xs muted">${f.startsWith("Mock") ? "A device signal, not proof." : f.startsWith("Possible") ? "Could be a shared family phone. Ask before deciding." : "They chose not to share location. That's allowed; the invitation and your judgement decide."}</p></div></div>`).join("")}</div>
    <form class="card card-pad-lg" id="md" style="border:1.5px solid var(--primary)"><h3>Decision</h3><div class="opts mt-4">${[["APPROVED", "Approve", "They can lend and borrow in Block C.", "user-check"], ["INFO_REQUESTED", "Ask for more information", "e.g. a utility bill showing the lane, account number hidden.", "message-square-text"], ["REJECTED", "Reject", "They're told why and can apply again.", "user-x"]].map(([v, t, x, ic], i) => `<label class="opt"><input type="radio" name="m" value="${v}" ${i === (m.locality_outcome === "VERIFIED" ? 0 : 1) ? "checked" : ""}>${tone(ic, "neutral", 34)}<span><strong>${t}</strong><p>${x}</p></span><span class="tick">${icon("check")}</span></label>`).join("")}</div>
      <div class="field"><label class="label" for="mw">Reason <span class="req">· the applicant sees this</span></label><textarea class="textarea" id="mw" maxlength="1000" style="min-height:80px"></textarea></div><button class="btn btn-primary mt-4" type="submit">Record decision</button></form></div>`;
  return { title: "Join requests", nav: "members", html: `${consoleHead("Join requests", `${open} people are waiting for a decision on joining Block C.`)}<div class="split-v ${m ? "sel" : ""}"><div class="qlist">${list}</div><div class="detail">${m ? `<a class="back mob" href="#/mod/members">${icon("arrow-left")}All requests</a>` : ""}${d}</div></div>`,
    after() {
      $("#md")?.addEventListener("submit", e => { e.preventDefault(); if (!$("#mw").value.trim()) { $("#mw").setAttribute("aria-invalid", "true"); $("#mw").focus(); return toast("Add a reason. The applicant sees it.", { ic: "info" }); } $(".detail").innerHTML = `<div class="card card-pad-lg">${done("Decision recorded", `${m.applicant_name.split(" ")[0]} has been told, with your reason.`)}<div class="btns" style="justify-content:center"><a class="btn btn-primary" href="#/mod/members">Next request</a></div></div>`; refreshIcons(); });
      $("#rv")?.addEventListener("click", () => dialog(`<h2>Reverse this approval?</h2><p class="small muted mt-1">Records a <span class="mono">REVERSED</span> decision that points to the original. Both stay in the log.</p><div class="field mt-4"><label class="label" for="rr">Reason (required)</label><textarea class="textarea" id="rr" maxlength="1000"></textarea></div><button class="btn btn-danger mt-4" data-close type="button" onclick="toast('Approval reversed')">Reverse</button>`, "Reverse"));
    } };
}
route("/mod/members", () => members(null));
route("/mod/members/:id", ({ id }) => members(id));

/* ---------------- I3 + I5: reports and automatic flags (iteration 3) ---------------- */
route("/mod/reports", () => ({ title: "Reports", nav: "reports", html: `${consoleHead("Reports and flags", "From members and from automatic screening. Nothing is ever removed automatically.")}${previewBar("The report queue and automatic screening (I3, I5)")}
  <div class="list mt-6" data-stagger>${DB.reports.map(r => `<div class="li" style="align-items:flex-start;flex-wrap:wrap">${tone(r.by.includes("Automatic") ? "bot" : "flag", r.prio === "high" ? "coral" : r.prio === "med" ? "saffron" : "sky", 38)}<span class="grow" style="min-width:220px"><span class="row-wrap"><span class="prio ${r.prio}">${icon(PRI[r.prio][1])}${PRI[r.prio][0]}</span><span class="badge">${r.what}</span><span class="xs faint">${r.by}</span></span><span class="t mt-1">${r.t}</span><span class="d">${r.why}</span></span><span class="btns"><button class="btn btn-outline btn-sm" type="button" onclick="toast('Kept, with reason logged')">Keep</button><button class="btn btn-outline btn-sm" type="button" onclick="toast('Warning sent')">Warn</button><button class="btn btn-danger btn-sm" type="button" onclick="toast('Removed. The author can appeal.')">Remove</button><button class="btn btn-ghost btn-sm" type="button" onclick="toast('Escalated to admin')">Escalate</button></span></div>`).join("")}</div>
  <p class="xs faint mt-4">${icon("info", "i-sm")} Reports clustered on one person are flagged as possible reporting abuse. Mixed Urdu and English text always goes to a person.</p>` }));
route("/mod/events", () => ({ title: "Event approvals", nav: "events", html: `${consoleHead("Event approvals", "Block C asks moderators to approve new events.")}${previewBar("Event approval (C2)")}
  <div class="grid-3 mt-6" data-stagger>${DB.events.slice(2, 5).map(e => `<div class="card" style="padding:0;overflow:hidden">${photo(e.photo, { w: 600, ratio: "16/9", alt: "" })}<div style="padding:16px"><span class="badge sky">${e.type}</span><h3 class="mt-2">${e.t}</h3><p class="small muted">${e.dow} ${e.day} ${e.mon} · ${e.where}</p><div class="row small mt-3">${av(e.org, "xs")}${U(e.org).name} · hosted 3 events</div><div class="btns mt-4"><button class="btn btn-primary btn-sm" type="button" onclick="toast('Published to Block C')">Approve</button><button class="btn btn-outline btn-sm" type="button" onclick="toast('Changes requested')">Request changes</button></div></div></div>`).join("")}</div>` }));

/* ---------------- W21: audit log (AuditEntryOut; masked until unmasked with a purpose) ---------------- */
function audit(admin, tamper) {
  const rows = DB.audit.map(e => tamper && e.id === 1281 ? { ...e, hash_valid: false } : e);
  const bad = rows.filter(e => !e.hash_valid);
  const row = e => `<tr class="${e.hash_valid ? "" : "bad"}" data-cat="${e.category}" data-out="${e.outcome}"><td class="mono xs">${e.id}<div class="faint">${e.source}</div></td><td class="mono xs" style="white-space:nowrap">${e.at}</td><td><b class="small" data-mask="${e.id}">${e.actor}</b><div class="mono xs faint">${e.authorisation}</div></td><td><span class="mono xs">${e.action}</span><div><span class="badge" style="height:20px;font-size:11px">${e.category}</span></div></td><td class="small">${e.target}<div class="xs muted">${e.summary}</div></td><td class="xs" style="white-space:nowrap">${e.prev ? `${e.prev} → <b>${e.next}</b>` : "—"}</td><td><span class="status ${e.outcome === "SUCCESS" ? "green" : "coral"}">${e.outcome}</span></td><td class="small">${e.reason || '<span class="faint">—</span>'}</td><td>${e.hash_valid ? `<span class="xs" style="color:var(--primary-ink)">${icon("check", "i-sm")}valid</span>` : `<span class="xs" style="color:var(--coral-ink)">${icon("x", "i-sm")}mismatch</span>`}</td><td>${e.masked && admin ? `<button class="btn btn-ghost btn-sm" type="button" data-unmask="${e.id}">${icon("eye")}Unmask</button>` : ""}</td></tr>`;
  return { title: "Audit log", nav: "audit", html: `${consoleHead("Audit log", "Every decision and state change, append-only.", `<button class="btn btn-outline btn-sm" type="button">${icon("download")}Export</button>`)}
    ${bad.length ? `<div class="card row" style="background:var(--coral-soft);border:0;align-items:flex-start">${tone("shield-alert", "coral", 38)}<div><b>Hash check failed at entry #${bad[0].id}</b><p class="small">Its contents no longer match its stored hash (<span class="mono">hash_valid: false</span>). Nothing was changed automatically.</p></div></div>`
      : `<div class="card card-2 row">${tone("shield-check", "green", 38)}<div><b class="small">Every entry's hash checks out</b><p class="xs muted">Entries can be added, never edited or deleted.</p></div></div>`}
    ${admin ? DB.concentration.map(k => `<div class="card card-2 row mt-4" style="align-items:flex-start">${tone("chart-no-axes-column", "saffron", 38)}<div><b class="small">Worth a second look: decision concentration</b><p class="xs muted">${k.moderator} made ${k.decisions} decisions about ${k.member} in 90 days, ${Math.round(k.share * 100)}% of their decisions (threshold: at least 3 and 60%). It may be fine. It's flagged for review, not as a finding.</p></div></div>`).join("") : ""}
    <div class="row-wrap mt-6"><div class="chips" data-chips id="acat">${["All", "DISPUTE", "MEMBERSHIP", "ASSURANCE", "OTHER"].map((t, i) => `<button class="chip" type="button" data-c="${t}" aria-pressed="${i === 0}">${t === "All" ? t : cap(t.toLowerCase())}</button>`).join("")}</div><div class="chips" data-chips id="aout">${["Any outcome", "SUCCESS", "REJECTED"].map((t, i) => `<button class="chip" type="button" data-o="${t}" aria-pressed="${i === 0}">${i ? cap(t.toLowerCase()) : t}</button>`).join("")}</div></div>
    <div class="table-w mt-4"><table class="table"><thead><tr><th>#</th><th>When</th><th>Who</th><th>Action</th><th>Target</th><th>State change</th><th>Outcome</th><th>Reason</th><th>Hash</th><th></th></tr></thead><tbody id="arows">${rows.map(row).join("")}</tbody></table></div>
    <p class="xs faint mt-3">${icon("eye-off", "i-sm")} Members are masked${admin ? ". Unmasking needs a purpose and is itself recorded" : ""}. Opening this log is recorded too.${admin && !tamper ? ` <a class="link" href="#/admin/audit/tamper">Prototype: show a hash mismatch</a>` : ""}</p>`,
    after() {
      let c = "All", o = "Any outcome";
      const f = () => $$("#arows tr").forEach(r => (r.hidden = !((c === "All" || r.dataset.cat === c) && (o === "Any outcome" || r.dataset.out === o))));
      $("#acat").addEventListener("click", e => { const b = e.target.closest("[data-c]"); if (b) { c = b.dataset.c; f(); } });
      $("#aout").addEventListener("click", e => { const b = e.target.closest("[data-o]"); if (b) { o = b.dataset.o; f(); } });
      $("#arows").addEventListener("click", e => { const b = e.target.closest("[data-unmask]"); if (!b) return; const id = b.dataset.unmask;
        dialog(`<h2>Unmask entry #${id}?</h2><p class="small muted mt-1">Shows the member's name for this entry. Your name, the time and your purpose are recorded in the log.</p><div class="field mt-4"><label class="label" for="up">Purpose (at least 10 characters)</label><textarea class="textarea" id="up" maxlength="500" style="min-height:80px" placeholder="e.g. Checking the concentration flag on Imran Q.'s decisions"></textarea><div id="ue"></div></div><button class="btn btn-primary mt-4" type="button" id="ug">Unmask</button>`, "Unmask");
        $("#ug").onclick = () => { if ($("#up").value.trim().length < 10) { $("#up").setAttribute("aria-invalid", "true"); $("#ue").innerHTML = `<p class="err">${icon("circle-alert")}Say why, in at least 10 characters.</p>`; refreshIcons(); return; }
          closeDialog(); const n = $(`[data-mask="${id}"]`); n.textContent = { 1281: "Tariq Mehmood", 1280: "Hira Aslam", 1279: "Usman Tariq" }[id] || n.textContent; b.remove(); toast("Unmasked. This view is recorded."); }; });
    } };
}
route("/mod/audit", () => audit(false));
route("/admin/audit", () => audit(true));
route("/admin/audit/tamper", () => audit(true, true));

/* ---------------- Scheduler (POST /internal/jobs/run -> JobReportOut) ---------------- */
route("/admin/jobs", () => ({ title: "Scheduled jobs", nav: "jobs", html: `${consoleHead("Scheduled jobs", "Timers that move loans along: expiry, no-shows, reminders and escalations.", `<button class="btn btn-primary btn-sm" type="button" id="run">${icon("play")}Run now</button>`)}
  <div class="card card-2 row">${tone("lock", "sky", 38)}<div><b class="small">Safe to run any time</b><p class="xs muted">One run at a time (a lock), and every job is idempotent: running twice never sends a notice twice or opens a second dispute. A failed job is retried on the next run.</p></div></div>
  <div class="table-w mt-6"><table class="table"><thead><tr><th>Job</th><th>What it does</th><th>Acted on</th><th>Skipped</th><th>Failed</th></tr></thead><tbody id="jrows">${DB.jobs.map(([k, l, d, r, s, f]) => `<tr><td><b class="small">${l}</b><div class="mono xs faint">${k}</div></td><td class="small">${d}</td><td class="mono" data-r>${r}</td><td class="mono faint">${s}</td><td>${f ? `<span class="status coral">${f}</span>` : '<span class="mono faint">0</span>'}</td></tr>`).join("")}</tbody></table></div>
  <p class="xs faint mt-3" id="jmeta">${icon("clock", "i-sm")} Last run 16 Oct, 08:00 · lock acquired · ${DB.jobs.length} jobs</p>`,
  after() { $("#run").onclick = () => { $("#run").setAttribute("aria-disabled", "true"); toast("Running…", { ic: "loader" }); setTimeout(() => { $$("#jrows [data-r]").forEach(c => (c.textContent = "0")); $("#jmeta").innerHTML = `${icon("clock", "i-sm")} Ran just now · lock acquired · nothing new to act on, as expected right after the last run`; refreshIcons(); $("#run").removeAttribute("aria-disabled"); toast("Run complete: 0 acted on, nothing duplicated"); }, 900); }; } }));

/* ---------------- J1: admin analytics ---------------- */
const chartLine = (pts, col = "var(--primary)") => { const W = 600, H = 160, mx = Math.max(...pts); const P = pts.map((v, i) => [i * W / (pts.length - 1), H - 10 - v / mx * (H - 30)]); const d = P.map((p, i) => (i ? "L" : "M") + p[0].toFixed(1) + " " + p[1].toFixed(1)).join("");
  return `<svg viewBox="0 0 ${W} ${H}" style="width:100%;height:auto" role="img" aria-label="Completed loans per week, rising"><defs><linearGradient id="lg" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="${col}" stop-opacity=".25"/><stop offset="1" stop-color="${col}" stop-opacity="0"/></linearGradient></defs>${[0, 1, 2, 3].map(i => `<line x1="0" x2="${W}" y1="${20 + i * 40}" y2="${20 + i * 40}" stroke="var(--border)"/>`).join("")}<path d="${d}L${W} ${H}L0 ${H}Z" fill="url(#lg)"/><path d="${d}" fill="none" stroke="${col}" stroke-width="2.5" stroke-dasharray="1400" stroke-dashoffset="1400" style="animation:draw 1.6s var(--ease) forwards"/>${P.map(([x, y]) => `<circle cx="${x}" cy="${y}" r="3.5" fill="var(--surface)" stroke="${col}" stroke-width="2"/>`).join("")}</svg>`; };
route("/admin", () => ({ title: "Analytics", nav: "dash", html: `${consoleHead("Platform analytics", "All 4 communities · last 30 days · synthetic demo data", `<div class="chips" data-chips>${["7 days", "30 days", "Term"].map((t, i) => `<button class="chip" type="button" aria-pressed="${i === 1}">${t}</button>`).join("")}</div>`)}${previewBar("Platform analytics (J1)")}
  <div class="grid-4 mt-6" data-stagger>${[["users", "green", 645, "Active members", "+38 this month"], ["package-check", "sky", 312, "Loans completed", "+18% vs last month"], ["scale", "coral", 3, "Open disputes", "Oldest 2 days"], ["hourglass", "violet", 7, "Requests held", "Median review 3.1 h"]].map(([ic, t, v, l, s]) => `<div class="card spot">${tone(ic, t)}<div class="kpi mt-4" data-count="${v}">0</div><b class="small">${l}</b><p class="xs faint">${s}</p></div>`).join("")}</div>
  <div class="grid-2 mt-6"><div class="card"><div class="between"><h3>Completed loans per week</h3><span class="badge green">${icon("trending-up")}Rising</span></div><div class="mt-4">${chartLine([12, 18, 15, 24, 22, 31, 29, 38, 42, 47])}</div></div>
    <div class="card"><h3>Evidence states on new requests</h3><p class="xs faint mt-1">They describe evidence for a loan, not people.</p><div class="bars mt-4">${[["Enough evidence", 54, "var(--primary)"], ["Review recommended", 21, "var(--saffron)"], ["Not enough history yet", 19, "var(--sky)"], ["Open dispute", 2, "var(--coral)"], ["Held for a moderator", 4, "var(--violet)"]].map(([l, v, c], i) => `<div class="br"><span class="small">${l}</span><span class="bt"><i style="width:${v}%;background:${c};animation-delay:${i * 80}ms"></i></span><b class="small">${v}%</b></div>`).join("")}</div></div></div>
  <div class="grid-2 mt-6"><div class="card"><h3>Communities</h3><div class="list mt-4">${DB.communities.map((c, i) => `<div class="li">${photo(c.photo, { w: 140, alt: "" })}<span class="grow"><span class="t">${c.name}</span><span class="d">${i === 2 ? "Fewer than 20 loans: figures hidden for privacy" : `${c.member_count} members · ${[168, 96, 0, 48][i]} loans`}</span></span>${i === 2 ? `<span class="badge">${icon("eye-off")}Hidden</span>` : ""}</div>`).join("")}</div></div>
    <div class="card"><div class="between"><h3>Other modules</h3>${soon()}</div><div class="grid-2 mt-4">${[["Forum posts", "—"], ["Assistant questions", "—"], ["Event registrations", "—"], ["Unanswered questions", "—"]].map(([l, v]) => `<div class="card card-2"><div class="xs faint">${l}</div><div class="kpi faint" style="font-size:1.4rem">${v}</div></div>`).join("")}</div><p class="xs faint mt-3">Tracked from iteration 3, once these modules launch.</p></div></div>` }));

/* ---------------- Admin management (iteration 3) ---------------- */
route("/admin/users", () => ({ title: "Users", nav: "users", html: `${consoleHead("Users and roles", "Suspend, ban or change roles, always with a reason.")}${previewBar("User management (I1)")}
  <div class="table-w mt-6"><table class="table" style="min-width:680px"><thead><tr><th>Person</th><th>Community</th><th>Role</th><th>Status</th><th></th></tr></thead><tbody>${["u0", "u2", "u4", "u5", "mod", "u3"].map((u, i) => `<tr><td><span class="row">${av(u, "sm")}<b class="small">${U(u).name}</b></span></td><td class="small">Block C</td><td><span class="badge ${u === "mod" ? "green" : ""}">${u === "mod" ? "Moderator" : "Member"}</span></td><td><span class="status ${i === 5 ? "saffron" : "green"}">${i === 5 ? "Warning issued" : "Active"}</span></td><td><button class="btn btn-ghost btn-sm" type="button" onclick="dialog('<h2>Change ${U(u).short}\\'s access</h2><div class=&quot;opts mt-6&quot;><label class=&quot;opt&quot;><input type=&quot;radio&quot; name=&quot;a&quot; checked><span><strong>Suspend 7 days</strong><p>Active loans continue with moderator help</p></span></label><label class=&quot;opt&quot;><input type=&quot;radio&quot; name=&quot;a&quot;><span><strong>Make moderator</strong></span></label></div><div class=&quot;field&quot;><label class=&quot;label&quot;>Reason (required)</label><textarea class=&quot;textarea&quot;></textarea></div><button class=&quot;btn btn-primary mt-4&quot; data-close>Save</button>','Access')">Manage</button></td></tr>`).join("")}</tbody></table></div>` }));
route("/admin/communities", () => ({ title: "Communities", nav: "communities", html: `${consoleHead("Communities and categories", "Boundaries, rules, verification methods and restricted categories.", `<button class="btn btn-primary btn-sm" type="button">${icon("plus")}New community</button>`)}${previewBar("Community management (I2)")}
  <div class="grid-2 mt-6" data-stagger>${DB.communities.map(c => `<div class="card" style="padding:0;overflow:hidden">${photo(c.photo, { w: 700, ratio: "16/7", alt: "" })}<div style="padding:16px"><div class="between"><h3>${c.name}</h3><span class="badge">${c.join_code}</span></div><p class="small muted mt-1">${c.member_count} members · ${c.methods.includes("GEOFENCE_INVITATION") ? "location check + invitation, or moderator approval" : "moderator approval only"}${c.has_boundary ? "" : " · no boundary set"}</p><div class="btns mt-4"><button class="btn btn-outline btn-sm" type="button">Edit rules</button><button class="btn btn-outline btn-sm" type="button">Boundary</button><button class="btn btn-ghost btn-sm" type="button">Deactivate</button></div></div></div>`).join("")}</div>
  <div class="card mt-6"><h3>Categories <span class="xs faint" style="font-weight:400">· GET /categories</span></h3><div class="row-wrap mt-4">${DB.categories.slice(1).map(c => `<span class="badge ${c.is_restricted ? "violet" : "outline"}" style="height:32px">${icon(c.icon)}${c.label}${c.is_restricted ? " · community-verified only" : ""}</span>`).join("")}</div></div>` }));
route("/admin/vendors", () => ({ title: "Vendor verification", nav: "vendors", html: `${consoleHead("Vendor verification", "Approve, reject or ask for more information.")}${previewBar("Vendor verification (H5)")}
  <div class="list mt-6">${DB.vendors.filter(v => !v.verified).map(v => `<div class="li" style="flex-wrap:wrap">${photo(v.photo, { w: 140, alt: "" })}<span class="grow"><span class="t">${v.name}</span><span class="d">${v.cat} · ${v.lane} · photo uploaded, no licence</span></span><span class="btns"><button class="btn btn-primary btn-sm" type="button" onclick="toast('Verified · badge added')">Verify</button><button class="btn btn-outline btn-sm" type="button" onclick="toast('Asked for a shop photo')">Ask for info</button><button class="btn btn-ghost btn-sm" type="button">Reject</button></span></div>`).join("")}</div>` }));
route("/admin/knowledge", () => ({ title: "Assistant knowledge", nav: "kb", html: `${consoleHead("Assistant knowledge base", "Approve, exclude or pin sources. Every source is screened for prompt injection before it's indexed.", `<button class="btn btn-outline btn-sm" type="button" onclick="toast('Re-indexing started')">${icon("refresh-cw")}Re-index</button>`)}${previewBar("Knowledge base management and content-gap report (F4, F5)")}
  <div class="grid-2 mt-6"><div class="card"><h3>Sources</h3><div class="list mt-4">${[["file-text", "Borrowing and return policy", "Policy · pinned", "green"], ["file-text", "Community rules · Block C", "Policy", "green"], ["calendar", "Events (live records)", "Structured · auto", "sky"], ["messages-square", "Forum answers marked best", "User content · weighted", "violet"], ["shield-alert", "Post “ignore previous instructions…”", "Withheld: injection-shaped", "coral"]].map(([ic, t, d, tn]) => `<div class="li">${tone(ic, tn, 34)}<span class="grow"><span class="t">${t}</span><span class="d">${d}</span></span><label class="switch"><input type="checkbox" ${tn !== "coral" ? "checked" : ""} aria-label="Include ${t}"></label></div>`).join("")}</div></div>
    <div class="card"><h3>Unanswered topics</h3><p class="xs faint mt-1">Questions the assistant abstained on this week.</p><div class="bars mt-4">${[["Water tanker rates", 14], ["Gas load-shedding times", 9], ["Parking rules", 6], ["School admissions", 4]].map(([l, v]) => `<div class="br"><span class="small">${l}</span><span class="bt"><i style="width:${v * 6}%;background:var(--saffron)"></i></span><b class="small">${v}</b></div>`).join("")}</div><div class="grid-2 mt-6"><div class="card card-2"><div class="xs faint">Abstention rate</div><div class="kpi" style="font-size:1.4rem">12%</div></div><div class="card card-2"><div class="xs faint">Reported wrong</div><div class="kpi" style="font-size:1.4rem">3</div></div></div></div></div>` }));

